package net.zartra.gui;
import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;import static org.junit.Assert.*;
public class Goal2ItemCopyTest {@Test public void deepCopyPreservesIndependentAdvancedRuntimeState(){MenuItem a=new MenuItem(new ItemStack(Material.STONE),null);a.priority=7;a.customModelData=4;a.enchantments.put("DURABILITY",2);a.conditions.entries.add(new ConditionEntry(ConditionEntry.Type.IS_OP,""));ActionEntry action=new ActionEntry();action.type="MESSAGE";a.actions(MenuClickType.LEFT).add(action);MenuItem b=a.copy();b.priority=1;b.enchantments.put("DURABILITY",3);b.conditions.entries.get(0).enabled=false;b.actions(MenuClickType.LEFT).get(0).value="changed";assertEquals(7,a.priority);assertEquals(Integer.valueOf(2),a.enchantments.get("DURABILITY"));assertTrue(a.conditions.entries.get(0).enabled);assertEquals("",a.actions(MenuClickType.LEFT).get(0).value);}}